const board = {
  title: "Sprint",
  columns: { todo: ["a", "b"], done: ["c"] },
};

const next = {
  ...board,
  columns: { ...board.columns, done: [...board.columns.done, "b"] },
};

console.log(board.columns.done.length);
console.log(next.columns === board.columns);
console.log(next.columns.todo === board.columns.todo);
console.log(next.columns.done.join(""));
